static FVM_Result attach(FVM_Context *c,FVM_Object *clip,FVM_Object *image,double depth,const char *snap="auto",bool smooth=false){FVM_Value args[4]={ref(image)};fvm_value_number(args+1,depth);fvm_value_string(args+2,snap);fvm_value_boolean(args+3,smooth);FVM_Value out;FVM_Result r=fvm_object_call(c,clip,"attachBitmap",4,args,&out);if(r==FVM_OK)assert(out.type==FVM_VALUE_UNDEFINED);return r;}
static FVM_Object *hidden(FVM_Object *clip,unsigned key){FVM_Object *children=clip->resource_result.object->properties["children"].object;return children->indexed[key+16384].object;}
static void green(FVM_Context *c,FVM_Object *clip){unsigned char pixels[256];if(render(c,clip,pixels)==FVM_OK){assert(pixels[0]==0 && pixels[1]==255 && pixels[2]==0 && pixels[3]==255);assert(pixels[4]==0 && pixels[5]==255 && pixels[6]==0 && pixels[7]==255);assert(pixels[8]==0 && pixels[9]==0 && pixels[10]==0 && pixels[11]==0);}}
static void restored(FVM_Context *c,FVM_Object *bundle){FVM_Object *clip=property(c,bundle,"clip"),*image=property(c,bundle,"image"),*node=hidden(clip,2);FVM_Object *path=node->resource_result.object->properties["paths"].object->indexed[0].object;assert(path->properties["bitmap"].object->properties["source"].object==image);assert(fvm_gc_pin(c,bundle)==FVM_OK);assert(fvm_gc_collect(c,0)==FVM_OK);green(c,clip);assert(attach(c,clip,image,3,"never")==FVM_OK);assert(hidden(clip,3)!=node);}
