FVM_Object *bundle=0;assert(fvm_object_create(c,&bundle)==FVM_OK);assert(fvm_gc_pin(c,bundle)==FVM_OK);FVM_Value value=ref(clip);assert(fvm_object_set(c,bundle,"clip",&value)==FVM_OK);value=ref(replacement);assert(fvm_object_set(c,bundle,"image",&value)==FVM_OK);FVM_Value packet=ref(bundle),out;FVM_Channel *ch=0;assert(fvm_channel_create(&ch)==FVM_OK);assert(fvm_channel_send_value(c,ch,&packet,0)==FVM_OK);assert(fvm_channel_receive_value(other,ch,&out,0)==FVM_OK);restored(other,out.object);fvm_channel_destroy(ch);
FVM_Result opened=fvm_channel_open_file("attach-bitmap-test.bin","w",&ch);if(opened==FVM_OK){assert(fvm_channel_send_value(c,ch,&packet,0)==FVM_OK);fvm_channel_destroy(ch);assert(fvm_channel_open_file("attach-bitmap-test.bin","r",&ch)==FVM_OK);assert(fvm_channel_receive_value(other,ch,&out,0)==FVM_OK);restored(other,out.object);fvm_channel_destroy(ch);assert(std::remove("attach-bitmap-test.bin")==0);}else assert(opened==FVM_UNSUPPORTED);
