write(c,replacement,0,0,0xff0000ffUL);if(render(c,clip,unsnapped)==FVM_OK)assert(unsnapped[2]==255 && unsnapped[1]==0);call(c,replacement,"dispose");if(render(c,clip,unsnapped)==FVM_OK)for(unsigned i=0;i<256;++i)assert(unsnapped[i]==0);
